// Already validated and projected onto this task's fields by "Normalize Input".
const variables = $input.first().json.variables;
return variables.map(v => ({ json: v }));

const item = $input.first().json;
const name = item.variable_name || '';
const label = item.variable_label || '';
let questionText = (item.variable_source_question || item.variable_description || '').trim();

questionText = questionText
  .replace(/\[MONTH,?\s*YEAR\]/gi, '')
  .replace(/please (choose|use|select) (an )?(answer from )?this card\.?/gi, '')
  .replace(/using (the same |this )?card[,.]/gi, '')
  .replace(/\s{2,}/g, ' ')
  .trim();

let queryText = `Thesaurus concept for variable "${name}": "${label}"`;
if (questionText) {
  queryText += `, asking: "${questionText}"`;
}

return [{ json: { queryText, variable: item } }];

// Collect skos:related neighbour URIs for the second-stage Supabase lookup.
//
// "Retrieve ELSST" runs with onError: continueRegularOutput, so on a Supabase
// failure it passes its INPUT item through untouched ({queryText, variable})
// instead of emitting documents. Detect that here so the failure is reported
// downstream instead of silently degrading into an empty concept list.
const items = $input.all();

const docs = [];
for (const item of items) {
  const j = item.json || {};
  const doc = j.document || j;
  if (doc.pageContent !== undefined || doc.metadata !== undefined) {
    docs.push(j);
  }
}

const retrievalFailed = docs.length === 0;

let retrievalError = '';
if (retrievalFailed) {
  const errItem = items.find(i => i.json && i.json.error);
  const err = errItem ? errItem.json.error : null;
  retrievalError = (err && (err.message || err.description)) ||
    'Supabase vector search returned no documents';
}

const metaOf = (doc) => (doc.document || {}).metadata || doc.metadata || {};

const primaryUris = new Set();
for (const doc of docs) {
  const meta = metaOf(doc);
  if (meta.uri) primaryUris.add(meta.uri);
}

const relatedUriSet = new Set();
for (const doc of docs) {
  let uriList = metaOf(doc).related_uris || [];
  if (typeof uriList === 'string') {
    try { uriList = JSON.parse(uriList); } catch (e) { uriList = []; }
  }
  for (const u of uriList) {
    if (u && !primaryUris.has(u)) relatedUriSet.add(u);
  }
}

// Cap the list so the generated GET stays well under any URL length limit;
// topK=15 can yield a lot of neighbours.
const relatedUris = [...relatedUriSet].slice(0, 40);

// Quote and percent-encode the values. encodeURIComponent would also escape the
// slashes inside the URIs, so keep those literal to match the form PostgREST was
// verified against.
const enc = (s) => encodeURIComponent(s).replace(/%2F/g, '/');
const quote = (v) => '"' + String(v).replace(/["\\]/g, '') + '"';
const lookupFilter = relatedUris.length
  ? 'metadata->>uri=' + enc('in.(' + relatedUris.map(quote).join(',') + ')')
  : 'limit=1';

return [{ json: { docs, relatedUris, lookupFilter, retrievalFailed, retrievalError } }];

// Build the RAG prompt from the primary similarity hits plus their skos:related
// neighbours.
const collectData = $('Collect Related URIs').first().json;
const primaryDocs = collectData.docs || [];
const expectedRelatedUris = new Set(collectData.relatedUris || []);

// Keep only rows that were actually requested. The upstream query falls back to
// limit=1 when there is nothing to look up, purely to keep the pipeline alive --
// drop that row here.
const relatedRows = [];
for (const item of $input.all()) {
  const body = item.json;
  const rows = Array.isArray(body)
    ? body
    : (body && (body.content !== undefined || body.metadata !== undefined) ? [body] : []);
  for (const row of rows) {
    if (expectedRelatedUris.has((row.metadata || {}).uri || '')) relatedRows.push(row);
  }
}

const variable = $('Build Query').first().json.variable || {};

// Primary candidates (full pageContent, no truncation)
// uri -> pref_label for every concept actually rendered into the prompt below.
// "Validate ELSST URIs" uses this as its allow-list, so it is built from the
// same two loops that render the text -- never reconstructed separately.
const allowedConcepts = {};

const primaryParts = primaryDocs.map((doc, i) => {
  const meta = (doc.document || {}).metadata || doc.metadata || {};
  const label = meta.pref_label || '(unknown)';
  const uri = meta.uri || '';
  const content = (doc.document || {}).pageContent || doc.pageContent || '';
  if (uri) allowedConcepts[uri] = meta.pref_label || '';
  return `[${i+1}] ${label}\nURI: ${uri}\n${content}`;
});

const relatedParts = relatedRows
  .map(row => {
    const meta = row.metadata || {};
    const label = meta.pref_label || '';
    const uri = meta.uri || '';
    const def = meta.definition || '';
    if (!label || !uri) return null;
    allowedConcepts[uri] = label;
    return `- ${label} (${uri})${def ? ': ' + def.substring(0, 300) : ''}`;
  })
  .filter(Boolean);

const primaryBlock = primaryParts.join('\n\n---\n\n');
const relatedBlock = relatedParts.length > 0
  ? '\n\n=== Related Concepts (thesaurus neighbours via skos:related) ===\n\n' + relatedParts.join('\n')
  : '';

const systemPrompt =
  'You are a metadata classification assistant for the European Language Social Science Thesaurus (ELSST).\n\n' +
  '=== Primary Candidates (retrieved by semantic similarity) ===\n\n' +
  primaryBlock +
  relatedBlock +
  '\n\n' +
  'Your task:\n' +
  '- The variable is given as JSON: variable_name, variable_label, variable_description, variable_source_question, variable_datatype, variable_format, variable_measure, variable_value_labels (at most the first 15 value/label pairs; variable_value_labels_total is the full count) and variable_missing_values. A missing field means it is unknown. Use them together to judge its subject matter.\n' +
  '- Select 1 to 3 ELSST concepts that best describe the SUBJECT MATTER of the variable.\n' +
  '- Each selected concept must appear in one of the lists above. Copy uri and pref_label exactly as shown.\n' +
  '- Prefer the most specific concept that accurately fits the variable.\n' +
  '- If the lists contain several narrow siblings sharing one broader concept, and the variable is about the general case rather than any single sibling, select that broader concept instead -- but only if it appears in the lists above.\n' +
  '- A concept naming the unit of observation (HOUSEHOLDS, INDIVIDUALS, FAMILIES) describes WHO is measured, not WHAT is measured. Select it only when the variable is genuinely about that unit (e.g. household size), not when it merely records whose attribute was captured.\n' +
  '- Exclude methodological concepts (data collection frequency, measurement scales, survey methods, data quality, etc.).\n' +
  '- Return an empty array only if the variable is clearly unrelated to all listed concepts (e.g., a technical ID or administrative code field).';

const userMessage = JSON.stringify(variable);
return [{ json: { systemPrompt, userMessage, allowedConcepts } }];

// Collect per-variable results from every loop iteration and tag each one, so the
// caller can tell "no matching concept" apart from "the lookup was broken".
// Both "Basic LLM Chain" and the retrieval-failure branch feed back into
// "Loop Over Items", so this sees a mix of LLM output and failure records.
const results = [];
let ok = 0;
let failed = 0;
const droppedUris = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const output = j.output;

  // "Validate ELSST URIs" records concepts the model invented. Surfacing the
  // count makes the hallucination rate measurable per run instead of guessed.
  if (Array.isArray(j.dropped_uris)) droppedUris.push(...j.dropped_uris);

  if (output && Array.isArray(output.results)) {
    for (const r of output.results) {
      const entry = { status: 'ok', ...r };
      results.push(entry);
      if (entry.status === 'ok') ok++; else failed++;
    }
    continue;
  }

  // No parsable output: "Basic LLM Chain" also runs with onError:
  // continueRegularOutput, so on failure it passes its input through and the
  // variable would otherwise vanish from the response entirely.
  // userMessage is JSON.stringify(variable), so the name is still recoverable.
  let variableName = '';
  try {
    variableName = JSON.parse(j.userMessage || '{}').variable_name || '';
  } catch (e) { /* leave blank */ }

  const err = j.error;
  results.push({
    variable_name: variableName,
    status: 'llm_failed',
    error: (err && (err.message || err.description)) ||
      'LLM chain produced no parsable output',
    elsst_concepts: [],
  });
  failed++;
}

return [{ json: { results, ok, failed, total: results.length, dropped: droppedUris.length, dropped_uris: droppedUris } }];

// Retrieval failed upstream - emit a record in the same shape "Basic LLM Chain"
// produces, so "Merge Results" can report it per item without burning an LLM call.
const j = $input.first().json || {};
const variable = $('Build Query').first().json.variable || {};

return [{
  json: {
    output: {
      results: [{
        variable_name: variable.variable_name || '',
        status: 'retrieval_failed',
        error: j.retrievalError || 'Supabase retrieval failed',
        elsst_concepts: [],
      }],
    },
  },
}];

// Reject any ELSST concept the model returned that was not in the candidate set
// rendered into its prompt. The output schema types uri/pref_label as free
// strings, so this is the only thing stopping a plausible but fabricated URI
// from reaching the caller -- the prompt instruction alone is not a constraint.
const item = $input.first().json || {};

// "Basic LLM Chain" runs with onError: continueRegularOutput -- on failure it
// passes its input straight through with no `output`. Leave those untouched so
// "Merge Results" still reports them as llm_failed.
if (!item.output || !Array.isArray(item.output.results)) {
  return [{ json: item }];
}

const allowed = ($('Build RAG Prompt').first().json || {}).allowedConcepts || {};
const dropped = [];

const results = item.output.results.map((r) => {
  const concepts = Array.isArray(r.elsst_concepts) ? r.elsst_concepts : [];
  const kept = [];
  const seen = new Set();

  for (const c of concepts) {
    const uri = (c && c.uri) || '';
    if (!Object.prototype.hasOwnProperty.call(allowed, uri)) {
      dropped.push({
        variable_name: r.variable_name || '',
        uri,
        pref_label: (c && c.pref_label) || '',
      });
      continue;
    }
    if (seen.has(uri)) continue;
    seen.add(uri);
    // Use the retrieved label, never the model's copy of it.
    kept.push({ uri, pref_label: allowed[uri] });
  }

  return { ...r, elsst_concepts: kept };
});

return [{ json: { output: { results }, dropped_uris: dropped } }];

// Normalize Input -- shared by every variable-enrichment workflow.
// Contract: schemas/variable_input.py (VariableInput). Generated by
// `python schemas/variable_input.py --node <task>`; edit the template, not the node.
// FIELDS is the subset of VariableInput this task's LLM sees (TASK_FIELDS["elsst"]).
const FIELDS = ["variable_label", "variable_description", "variable_source_question", "variable_datatype", "variable_format", "variable_measure", "variable_value_labels", "variable_value_labels_total", "variable_missing_values"];
const MAX_VALUE_LABELS = 15;
const LEGACY = { label: 'variable_label', description: 'variable_description', source_question: 'variable_source_question' };

// Webhook puts the payload under body; the Execute Workflow Trigger does not.
const input = $input.first().json;
const variables = input.body ? input.body.variables : input.variables;

const fail = (error) => [{ json: { valid: false, error } }];
if (!Array.isArray(variables) || variables.length === 0) {
  return fail('Expected a non-empty "variables" array of VariableInput objects.');
}

const isEmpty = (v) => v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0);
const out = [];

for (const [i, v] of variables.entries()) {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return fail(`variables[${i}] is not an object.`);
  if (typeof v.variable_name !== 'string' || !v.variable_name) return fail(`variables[${i}] is missing variable_name.`);

  const legacy = Object.keys(LEGACY).filter((k) => k in v);
  if (legacy.length) {
    const hint = legacy.map((k) => `${k} -> ${LEGACY[k]}`).join(', ');
    return fail(`variables[${i}] (${v.variable_name}) uses legacy keys; rename ${hint}.`);
  }

  const labels = (Array.isArray(v.variable_value_labels) ? v.variable_value_labels : [])
    .filter((l) => l && l.value !== undefined && l.label !== undefined)
    .map((l) => ({ value: String(l.value), label: String(l.label) }));
  const full = {
    ...v,
    variable_value_labels: labels.slice(0, MAX_VALUE_LABELS),
    variable_value_labels_total: labels.length ? (v.variable_value_labels_total ?? labels.length) : null,
  };

  const item = { variable_name: v.variable_name };
  for (const f of FIELDS) {
    if (!isEmpty(full[f])) item[f] = full[f];
  }
  out.push(item);
}

return [{ json: { valid: true, variables: out } }];
